int clampPercent(int value) {
  if (value < 0) return 0;
  if (value > 100) return 100;
  return value;
}
void setup() {
  Serial.begin(9600);
  for (int request = -20; request <= 120; request += 70) {
    Serial.println(clampPercent(request));
  }
}
void loop() { delay(100); }

