String frame = "";
bool discarding = false;
void setup() { Serial.begin(9600); Serial.println("Ready"); }
void loop() {
  while (Serial.available() > 0) {
    char ch = Serial.read();
    if (ch == '\r') continue;
    if (ch == '\n' || ch == ';') {
      if (discarding) Serial.println("Too long");
      else if (frame == "ON") Serial.println("Accepted ON");
      else if (frame == "OFF") Serial.println("Accepted OFF");
      else if (frame.length() > 0) Serial.println("Unknown");
      frame = "";
      discarding = false;
    } else if (!discarding) {
      if (frame.length() < 8) frame += ch;
      else { frame = ""; discarding = true; }
    }
  }
  delay(1);
}

enum Phase { STOP, GO, WAIT };
int phase = STOP;
unsigned long enteredAt = 0;
void enterPhase(int next) {
  phase = next;
  enteredAt = millis();
  if (phase == STOP) Serial.println("STOP");
  else if (phase == GO) Serial.println("GO");
  else Serial.println("WAIT");
}
void setup() { Serial.begin(9600); enterPhase(STOP); }
void loop() {
  unsigned long elapsed = millis() - enteredAt;
  switch (phase) {
    case STOP: if (elapsed >= 300UL) enterPhase(GO); break;
    case GO: if (elapsed >= 200UL) enterPhase(WAIT); break;
    case WAIT: if (elapsed >= 100UL) enterPhase(STOP); break;
    default: enterPhase(STOP); break;
  }
  delay(1);
}

#include <WiFi.h>
#include <WebServer.h>
WebServer server(80);
bool ledOn = false;
void setLed(bool on) {
  ledOn = on;
  digitalWrite(18, on ? HIGH : LOW);
}
void sendState() {
  server.send(200, "text/plain", ledOn ? "ON" : "OFF");
}
void turnOn() { setLed(true); sendState(); }
void turnOff() { setLed(false); sendState(); }
void setup() {
  Serial.begin(9600);
  pinMode(18, OUTPUT);
  setLed(false);
  WiFi.softAP("CourseLab", "coursepass");
  server.on("/on", turnOn);
  server.on("/off", turnOff);
  server.on("/status", sendState);
  server.begin();
  Serial.println("HTTP ready");
}
void loop() { server.handleClient(); delay(1); }

#include <WiFi.h>
#include <PubSubClient.h>
WiFiClient transport;
PubSubClient client(transport);
bool ledOn = false;
unsigned long acceptedAt = 0;
void applyCommand(String command) {
  if (command != "ON" && command != "OFF") return;
  ledOn = command == "ON";
  if (ledOn) acceptedAt = millis();
  digitalWrite(18, ledOn ? HIGH : LOW);
  client.publish("course/state", ledOn ? "ON" : "OFF");
  Serial.println(ledOn ? "ON" : "OFF");
}
void receive(char* topic, byte* payload, unsigned int length) {
  if (String(topic) != "course/cmd" || length > 3) return;
  String command = "";
  for (unsigned int i = 0; i < length; i++) command += char(payload[i]);
  applyCommand(command);
}
void setup() {
  Serial.begin(9600);
  pinMode(18, OUTPUT);
  digitalWrite(18, LOW);
  WiFi.begin("VoltNet", "");
  unsigned long started = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - started < 3000UL) delay(10);
  client.setServer("broker.voltquest", 1883);
  client.setCallback(receive);
  if (WiFi.status() == WL_CONNECTED && client.connect("course-controller")) {
    client.subscribe("course/cmd");
    Serial.println("MQTT ready");
  } else Serial.println("Offline: local control only");
}
void loop() {
  client.loop();
  if (Serial.available() > 0) {
    char key = Serial.read();
    if (key == '1') applyCommand("ON");
    else if (key == '0') applyCommand("OFF");
  }
  if (ledOn && millis() - acceptedAt >= 2000UL) applyCommand("OFF");
  delay(1);
}
